mapper.select:
SELECT fulfillment.id, fulfillment.erp_tenant_id, owner.tenant_name AS owner_name, fulfillment.warehouse_id, warehouse.warehouse_name, fulfillment.fulfillment_no, fulfillment.source_type, fulfillment.source_order_no, fulfillment.fulfillment_status, fulfillment.recipient_name, fulfillment.logistics_product_name, fulfillment.logistics_product_actual_fee, fulfillment.logistics_product_currency, fulfillment.carrier_name, fulfillment.shipping_method, fulfillment.tracking_no, fulfillment.package_weight_kg, COALESCE(fulfillment.handover_status, CASE WHEN fulfillment.fulfillment_status = 'SHIPPED' THEN 'HANDED_OVER' ELSE 'READY_HANDOVER' END) AS handover_status, fulfillment.vehicle_plate, fulfillment.driver_name, fulfillment.driver_phone, fulfillment.departure_time, fulfillment.handover_destination, fulfillment.recorded_freight_cost, fulfillment.recorded_freight_currency, fulfillment.logistics_photo_file_ids, fulfillment.handover_remark, fulfillment.handover_by, COALESCE(NULLIF(handover_user.nickname, ''), handover_user.username) AS handover_by_name, fulfillment.handover_time, fulfillment.shipped_by, COALESCE(NULLIF(shipped_user.nickname, ''), shipped_user.username) AS shipped_by_name, fulfillment.shipped_time, fulfillment.create_time FROM wms_fulfillment_order fulfillment LEFT JOIN sys_tenant owner ON owner.id = fulfillment.erp_tenant_id AND owner.deleted = 0 LEFT JOIN wms_warehouse warehouse ON warehouse.id = fulfillment.warehouse_id AND warehouse.deleted = 0 LEFT JOIN sys_user shipped_user ON shipped_user.user_id = fulfillment.shipped_by AND shipped_user.deleted = 0 LEFT JOIN sys_user handover_user ON handover_user.user_id = fulfillment.handover_by AND handover_user.deleted = 0
fulfillment.deleted = 0 AND fulfillment.fulfillment_status IN ('PACKED', 'SHIPPED')
AND fulfillment.erp_tenant_id = #{query.erpTenantId}
AND fulfillment.warehouse_id = #{query.warehouseId}
AND COALESCE(fulfillment.handover_status, CASE WHEN fulfillment.fulfillment_status = 'SHIPPED' THEN 'HANDED_OVER' ELSE 'READY_HANDOVER' END) = #{query.fulfillmentStatus}
AND fulfillment.handover_by = #{query.shippedBy}
AND fulfillment.create_time >= #{query.startDate}
AND fulfillment.create_time < DATE_ADD(#{query.endDate}, INTERVAL 1 DAY)
ORDER BY fulfillment.create_time DESC, fulfillment.id DESC
